"""Algorithm B: inversion of a leading-fraction mass to a window ratio.

The harmonic window law with endpoint ratio r > 1 assigns to the leading
u-fraction of the window the mass F_r(u) = log(1 + (r-1)u) / log r.  For each
fixed u in (0,1) the map r -> F_r(u) is a strictly increasing bijection from
(1, oo) onto (u, 1), so an observed mass determines the ratio uniquely.  This
module inverts it by bisection on log r, seeded by the analytic brackets

    F_r(u) <= u * r          (pins down small masses),
    F_r(u) >  1 + log(u)/log(r)  (pins down large masses).

Cost: O(log(1/tol)) evaluations of a logarithm; no derivatives required.
"""

from __future__ import annotations

import math
from typing import Callable


def harm_cdf(r: float, u: float) -> float:
    """F_r(u) = log(1 + (r-1)u) / log r."""
    if r <= 1.0:
        raise ValueError("window ratio must exceed 1")
    return math.log1p((r - 1.0) * u) / math.log(r)


def harm_decile_mass(r: float, k: int) -> float:
    """Mass of the k-th decile, k = 0..9."""
    return harm_cdf(r, (k + 1) / 10.0) - harm_cdf(r, k / 10.0)


def bracket_ratio(mass: float, u: float) -> tuple[float, float]:
    """Return (lo, hi) in log-ratio coordinates with F_lo(u) < mass < F_hi(u)."""
    lo = math.log(1.0 + 1e-12)               # F_r(u) -> u as r -> 1+
    hi = math.log(1.0 / u) / (1.0 - mass) + 1.0   # from the logarithmic bracket
    return lo, hi


def invert_leading_mass(mass: float, u: float = 0.1, tol: float = 1e-13) -> float:
    """Unique r > 1 with F_r(u) = mass, for mass in (u, 1)."""
    if not (u < mass < 1.0):
        raise ValueError(f"mass {mass} must lie strictly between {u} and 1")
    lo, hi = bracket_ratio(mass, u)
    while hi - lo > tol:
        mid = 0.5 * (lo + hi)
        if harm_cdf(math.exp(mid), u) < mass:
            lo = mid
        else:
            hi = mid
    return math.exp(0.5 * (lo + hi))


def invert_edge_decile(mass: float, tol: float = 1e-13) -> float:
    """Window ratio implied by an observed edge-decile (leading tenth) mass."""
    return invert_leading_mass(mass, u=0.1, tol=tol)


def profile_from_edge(mass: float) -> list[float]:
    """Full ten-bin harmonic profile implied by an edge-decile mass."""
    r = invert_edge_decile(mass)
    return [harm_decile_mass(r, k) for k in range(10)]


def compare_strata(masses: dict[str, float]) -> dict[str, float]:
    """Window ratios implied by the edge-decile mass of each rate stratum.

    Two strata share an edge-decile mass if and only if they share a window
    ratio, so the spread of the returned values measures exactly the geometric
    contrast between the strata.
    """
    return {name: invert_edge_decile(m) for name, m in masses.items()}
